export const gradeE3EigoBQuestions: Question[] = [
  {"id": "grade_e3_eigo_b001", "subject": "eigo", "question": "カタカナの「ジュース」を、えい語で書くとどれですか。", "answer": "juice", "hint": "日本語のカタカナと、えい語のつづりはちがうことがあるよ。", "explanation": "【何を聞かれているか】カタカナの「ジュース」を、えい語で書くとどれですか。\n\n【なぜそうなるのか】カタカナのことばはえい語から来たものが多いけれど、つづりはえい語のきまりで決まっていて、音のとおりには書かない。「ジュース」は j・u・i・c・e の5文字で書くから。\n\n【ステップ1】ジュースは、えい語から日本に来たことばだと考える。\n【ステップ2】えい語では j・u・i・c・e の5文字で書く。\n【ステップ3】3つの中で、この5文字がこのじゅんにならんでいるのは juice だけ。\n\n【答え】juice\n\n【たしかめ】juice を声に出すと、日本語の「ジュース」に近い音で、ゆびで数えると5文字になる。\n\n【よくあるまちがい】音のとおりに jusu や juse のように書いてしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["juice", "juse", "jooce"]},
  {"id": "grade_e3_eigo_b002", "subject": "eigo", "question": "カタカナの「ミルク」を、えい語で書きましょう。mではじまるえい語です。", "answer": "milk", "hint": "ぎゅうにゅうのパックに書いてあるよ。", "explanation": "【何を聞かれているか】カタカナの「ミルク」を、えい語で書きましょう。\n\n【なぜそうなるのか】「ミルク」はえい語の milk から来たことばで、えい語でも日本語でも、ぎゅうにゅうのことを言うから。つづりは m・i・l・k の4文字。\n\n【ステップ1】「ミルク」は、えい語から来たことばだと考える。\n【ステップ2】mではじまる4文字のえい語を思い出す。\n【ステップ3】m・i・l・k と1文字ずつ書く。\n\n【答え】milk\n\n【たしかめ】milk を声に出して、「ミルク」に近い音か聞いてみる。ゆびで数えて4文字になるか見る。\n\n【よくあるまちがい】さいごを g にして milg と書いてしまう。k で終わる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b003", "subject": "eigo", "question": "えい語のチャンツでは、手をたたきながら、ことばを何にのせて言いますか。カタカナで書きましょう。", "answer": "リズム", "hint": "おんがくで、手をたたくときのテンポのことだよ。", "explanation": "【何を聞かれているか】えい語のチャンツでは、手をたたきながら、ことばを何にのせて言いますか。\n\n【なぜそうなるのか】チャンツは、手をたたいたり足ぶみをしたりして、ことばを一定のリズムにのせて言うあそびだから。リズムにのせると、ことばをおぼえやすく、言いやすくなる。\n\n【ステップ1】チャンツは、ことばをうたうように言うあそびだと考える。\n【ステップ2】手をたたくと、同じ間かくの音が出る。\n【ステップ3】その間かくに合わせてことばを言うので、のせるのは「リズム」。\n\n【答え】リズム\n\n【たしかめ】手を3回たたいて、その音に合わせて Hello. と言ってみる。ことばと手の音がそろえば、リズムにのっている。\n\n【よくあるまちがい】音の高さの「メロディー」と、手をたたく間かくの「リズム」を言いまちがえる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b004", "subject": "eigo", "question": "友だちに「Do you like apples?」と聞かれて、「Yes.」と言いたいとき、日本でふつうに使うジェスチャーはどれですか。", "answer": "首をたてにふる", "hint": "ことばがわからなくても、見て「はい」とわかる動きだよ。", "explanation": "【何を聞かれているか】友だちに「Do you like apples?」と聞かれて、「Yes.」と言いたいとき、日本でふつうに使うジェスチャーはどれですか。\n\n【なぜそうなるのか】日本では、首をたてにふると「はい」の気持ちが相手につたわる。ジェスチャーは、ことばといっしょに使うと、気持ちがもっとよくつたわるから。\n\n【ステップ1】「Yes.」は「はい」の意味だと考える。\n【ステップ2】日本では「はい」のとき、どう動くか思い出す。\n【ステップ3】首をたてにふるのが「はい」。よこにふると「いいえ」になる。\n\n【答え】首をたてにふる\n\n【たしかめ】友だちに Yes. と言いながら首をたてにふってみて、「はい」だと思ってもらえるか聞く。\n\n【よくあるまちがい】首をよこにふってしまう。よこにふるのは「いいえ」の動き。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["首をよこにふる", "手を上げる", "首をたてにふる"]},
  {"id": "grade_e3_eigo_b005", "subject": "eigo", "question": "先生の言ったことが聞きとれませんでした。もう一度言ってほしいとき、えい語で言うのはどれですか。", "answer": "Pardon?", "hint": "聞きかえすときのことばだよ。", "explanation": "【何を聞かれているか】先生の言ったことが聞きとれませんでした。\n\n【なぜそうなるのか】Pardon? は「もう一度言ってください」と聞きかえすときのことばだから。わからないままにしないで聞きかえすと、あとでわかるようになる。\n\n【ステップ1】「聞きとれなかったから、もう一度」という場面だと考える。\n【ステップ2】Goodbye. はわかれ、Thank you. はお礼のことば。\n【ステップ3】聞きかえすことばは Pardon? だけ。\n\n【答え】Pardon?\n\n【たしかめ】3つのことばの意味を1つずつ日本語で言ってみて、「もう一度」にあたるのが Pardon? だけだとたしかめる。\n\n【よくあるまちがい】Thank you.（ありがとう）を、聞きかえすことばだと思ってしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["Goodbye.", "Pardon?", "Thank you."]},
  {"id": "grade_e3_eigo_b006", "subject": "eigo", "question": "お店のドアに「OPEN」と書いてあります。お店はどうなっていますか。", "answer": "あいている", "hint": "店の前で見るふだに、よく書いてあるよ。", "explanation": "【何を聞かれているか】お店のドアに「OPEN」と書いてあります。\n\n【なぜそうなるのか】OPEN は「あいている」という意味のえい語で、お店がやっているときにドアにかけるから。しまっているときは、ちがうことばが書いてある。\n\n【ステップ1】ドアに書いてあるえい語を読む。\n【ステップ2】OPEN は「あける」「あいている」という意味。\n【ステップ3】お店はやっているので、「あいている」。\n\n【答え】あいている\n\n【たしかめ】open の意味を、ドアをあける動きといっしょに言ってみる。あけるのだから「あいている」になる。\n\n【よくあるまちがい】「しまっている」だと思ってしまう。ドアがひらくイメージで考える。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["しまっている", "おやすみ", "あいている"]},
  {"id": "grade_e3_eigo_b007", "subject": "eigo", "question": "えい語で話すとき、相手の何を見て話すとよいですか。漢字1字で書きましょう。", "answer": "目", "hint": "話すとき、顔のどこを見るとつたわりやすいかな。", "explanation": "【何を聞かれているか】えい語で話すとき、相手の何を見て話すとよいですか。\n\n【なぜそうなるのか】相手の目を見て話すと、「あなたに話しているよ」という気持ちがつたわり、聞いている人も安心するから。えい語のじゅぎょうでも同じ。\n\n【ステップ1】話すときの、よいやり方を考える。\n【ステップ2】相手の顔の中で、気持ちがいちばんつたわるところを思い出す。\n【ステップ3】それは「目」。\n\n【答え】目\n\n【たしかめ】友だちと向かい合って、目を見ながら Hello. と言ってみる。気持ちがつたわったかを聞く。\n\n【よくあるまちがい】ノートや下ばかり見て話してしまう。前を向いて相手を見る。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b008", "subject": "eigo", "question": "えい語は、日本だけで使われていることばですか。「はい」か「いいえ」で答えましょう。", "answer": "いいえ", "hint": "世界にはたくさんの国があるよ。", "explanation": "【何を聞かれているか】えい語は、日本だけで使われていることばですか。\n\n【なぜそうなるのか】えい語は、アメリカやオーストラリアなど、世界のたくさんの国で使われていることばだから。日本だけではない。\n\n【ステップ1】えい語を使っている国を思い出す。\n【ステップ2】アメリカやオーストラリアでも、えい語が使われている。\n【ステップ3】日本だけではないので、答えは「いいえ」。\n\n【答え】いいえ\n\n【たしかめ】世界地図で、日本のほかにえい語の国を1つ見つけられたら、「いいえ」で正しい。\n\n【よくあるまちがい】「はい」と答えてしまう。日本で習うからといって、日本だけのことばではない。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b009", "subject": "eigo", "question": "朝（あさ）に会ったときのあいさつは、「Good ○○.」です。○○に入るえい語を書きましょう。", "answer": "morning", "hint": "「朝」をあらわすえい語だよ。mではじまるよ。", "explanation": "【何を聞かれているか】朝（あさ）に会ったときのあいさつは、「Good ○○.」です。\n\n【なぜそうなるのか】朝のあいさつは Good morning. と決まっていて、morning が「朝」という意味だから。朝に会ったら、朝という意味のことばを入れる。\n\n【ステップ1】「朝に会ったとき」のあいさつだと考える。\n【ステップ2】「朝」をあらわすえい語は morning。\n【ステップ3】Good のあとに morning を入れて Good morning. になる。\n\n【答え】morning\n\n【たしかめ】Good morning. を声に出して言い、「おはよう」の意味になっているか日本語でたしかめる。\n\n【よくあるまちがい】夜のあいさつの night を入れてしまう。night は「夜」のことば。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b010", "subject": "eigo", "question": "夕方（ゆうがた）に友だちに会いました。あいさつとして合うのはどれですか。", "answer": "Good evening.", "hint": "空が赤くなるころのあいさつだよ。", "explanation": "【何を聞かれているか】夕方（ゆうがた）に友だちに会いました。\n\n【なぜそうなるのか】evening は「夕方から夜のはじめ」をあらわすことばで、夕方に会うときのあいさつは Good evening. になるから。\n\n【ステップ1】「夕方に会った」という場面を考える。\n【ステップ2】morning は朝、night はねる前や夜のわかれ、evening は夕方。\n【ステップ3】夕方にぴったりなのは evening。\n\n【答え】Good evening.\n\n【たしかめ】3つのあいさつを、朝・夕方・夜のどれかに分けてみる。夕方に入るのは Good evening. だけ。\n\n【よくあるまちがい】Good night. を「こんばんは」の意味だと思ってしまう。Good night. はわかれのあいさつ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["Good evening.", "Good morning.", "Good night."]},
  {"id": "grade_e3_eigo_b011", "subject": "eigo", "question": "ねる前に、家の人に言うあいさつは、「Good ○○.」です。○○に入るえい語を書きましょう。", "answer": "night", "hint": "お休みなさいのときのことばだよ。nではじまるよ。", "explanation": "【何を聞かれているか】ねる前に、家の人に言うあいさつは、「Good ○○.」です。\n\n【なぜそうなるのか】ねる前や、夜にわかれるときのあいさつは Good night. で、night が「夜」という意味だから。「おやすみなさい」にあたる。\n\n【ステップ1】「ねる前」のあいさつだと考える。\n【ステップ2】「夜」をあらわすえい語は night。\n【ステップ3】Good night. で「おやすみなさい」の意味になる。\n\n【答え】night\n\n【たしかめ】Good night. と言って、日本語で「おやすみなさい」の意味になるか言ってみる。\n\n【よくあるまちがい】会うときのあいさつだと思って、昼の友だちに言ってしまう。わかれのときに使う。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b012", "subject": "eigo", "question": "「Good afternoon.」は、いつのあいさつですか。", "answer": "ひるすぎ", "hint": "afternoon は、昼のあとの時間をあらわすよ。", "explanation": "【何を聞かれているか】「Good afternoon.」は、いつのあいさつですか。\n\n【なぜそうなるのか】afternoon は、昼をすぎてから夕方になる前ごろの時間をあらわすことばだから。あいさつに使うと、ひるすぎの「こんにちは」の気持ちになる。\n\n【ステップ1】Good afternoon. のことばの意味を考える。\n【ステップ2】morning は朝、afternoon は昼のあと、night は夜。\n【ステップ3】「昼のあと」にあたるのは「ひるすぎ」。\n\n【答え】ひるすぎ\n\n【たしかめ】一日を朝・ひるすぎ・夕方・夜に分けて、afternoon がどこに入るか指でさしてみる。\n\n【よくあるまちがい】「あさ」と答えてしまう。朝は Good morning. のとき。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["あさ", "ひるすぎ", "ねるまえ"]},
  {"id": "grade_e3_eigo_b013", "subject": "eigo", "question": "「Thank you.」と言われたときの返事は、どれですか。", "answer": "You're welcome.", "hint": "お礼を言われたときに、「どういたしまして」と言うよ。", "explanation": "【何を聞かれているか】「Thank you.」と言われたときの返事は、どれですか。\n\n【なぜそうなるのか】Thank you. は「ありがとう」で、返事は「どういたしまして」の意味の You're welcome. だから。お礼を言われたら、これで気持ちよく答えられる。\n\n【ステップ1】「Thank you.」は「ありがとう」という意味。\n【ステップ2】お礼を言われたら、「どういたしまして」と答える。\n【ステップ3】「どういたしまして」は You're welcome. 。\n\n【答え】You're welcome.\n\n【たしかめ】友だちと2人で、「Thank you.」「You're welcome.」と言い合ってみる。会話になればよい。\n\n【よくあるまちがい】Goodbye. と言ってしまう。Goodbye. は、わかれるときのことば。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["You're welcome.", "Goodbye.", "Good morning."]},
  {"id": "grade_e3_eigo_b014", "subject": "eigo", "question": "「Thank you.」は、日本語で何と言うことばですか。ひらがなで書きましょう。", "answer": "ありがとう", "hint": "お礼を言うときのことばだよ。", "explanation": "【何を聞かれているか】「Thank you.」は、日本語で何と言うことばですか。\n\n【なぜそうなるのか】Thank you. は、何かをしてもらったときに言うお礼のことばで、日本語の「ありがとう」と同じ意味だから。\n\n【ステップ1】Thank you. を使う場面を考える。\n【ステップ2】物をもらったり、てつだってもらったりしたとき。\n【ステップ3】その気持ちを日本語で言うと「ありがとう」。\n\n【答え】ありがとう\n\n【たしかめ】ありがとうと言うつもりで、Thank you. と言ってみて、同じ気持ちになるかたしかめる。\n\n【よくあるまちがい】「ごめんなさい」と答えてしまう。ごめんなさいは Sorry. 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b015", "subject": "eigo", "question": "友だちとわかれるときに言うのは、「Hello.」と「Goodbye.」のどちらですか。えい語で書きましょう。", "answer": "Goodbye.", "hint": "「さようなら」の意味のほうだよ。", "explanation": "【何を聞かれているか】友だちとわかれるときに言うのは、「Hello.」と「Goodbye.」のどちらですか。\n\n【なぜそうなるのか】Hello. は会ったときのあいさつで、Goodbye. はわかれるときのあいさつだから。わかれるときは、会うときとちがうことばを使う。\n\n【ステップ1】「わかれるとき」だと考える。\n【ステップ2】Hello. は「こんにちは」、Goodbye. は「さようなら」。\n【ステップ3】わかれのことばは Goodbye. 。\n\n【答え】Goodbye.\n\n【たしかめ】2つを日本語にして、「さようなら」になるほうをえらぶ。Goodbye. が「さようなら」。\n\n【よくあるまちがい】Hello. にも「さようなら」の意味があると思ってしまう。Hello. は会うときだけ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b016", "subject": "eigo", "question": "はじめて会った人に言うあいさつは、「Nice to ○○ you.」です。○○に入るえい語を書きましょう。", "answer": "meet", "hint": "「会う」という意味のえい語だよ。mではじまるよ。", "explanation": "【何を聞かれているか】はじめて会った人に言うあいさつは、「Nice to ○○ you.」です。\n\n【なぜそうなるのか】Nice to meet you. は「はじめまして」の意味で、meet が「会う」だから。「あなたに会えてうれしい」という気持ちをあらわす。\n\n【ステップ1】「はじめて会った人」へのあいさつだと考える。\n【ステップ2】「会う」をあらわすえい語は meet。\n【ステップ3】Nice to meet you. で「はじめまして」になる。\n\n【答え】meet\n\n【たしかめ】Nice to meet you. を言ってみて、「はじめまして」の気持ちになっているか言いかえてみる。\n\n【よくあるまちがい】meat（にく）とまちがえる。つづりは m・e・e・t 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b017", "subject": "eigo", "question": "自分の名前を言うとき、「I'm ○○.」と言います。○○に入るのは自分の何ですか。漢字2字で書きましょう。", "answer": "名前", "hint": "「Ken」や「Mai」のようなものだよ。", "explanation": "【何を聞かれているか】自分の名前を言うとき、「I'm ○○.」と言います。\n\n【なぜそうなるのか】I'm Ken. は「ぼくはケンです」という意味で、I'm のあとには自分の名前を入れて言うから。\n\n【ステップ1】「I'm ○○.」の使い方を考える。\n【ステップ2】I'm Ken. の Ken は、人を表すよび名。\n【ステップ3】それは自分の「名前」。\n\n【答え】名前\n\n【たしかめ】I'm のあとに自分の名前を入れて、自分のことをしょうかいしてみる。名前が入っていれば正しい。\n\n【よくあるまちがい】年れいやすきなものを入れてしまう。I'm のあとは名前のほかに気持ちも入るが、ここでは名前。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b018", "subject": "eigo", "question": "「What's your name?」は、何をたずねるえい語ですか。", "answer": "あなたの名前は何ですか。", "hint": "name は「名前」のことだよ。", "explanation": "【何を聞かれているか】「What's your name?」は、何をたずねるえい語ですか。\n\n【なぜそうなるのか】What's は「何ですか」、your name は「あなたの名前」の意味だから、全体で名前をたずねる言い方になる。\n\n【ステップ1】言葉を分けて意味を考える。\n【ステップ2】What's は「何ですか」、your name は「あなたの名前」。\n【ステップ3】つなげると「あなたの名前は何ですか。」。\n\n【答え】あなたの名前は何ですか。\n\n【たしかめ】2人で、「What's your name?」「I'm Mai.」と言い合ってみる。名前が言えれば正しい。\n\n【よくあるまちがい】How old are you? とまちがえて、年れいをたずねる言い方だと思ってしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["あなたは何才ですか。", "元気ですか。", "あなたの名前は何ですか。"]},
  {"id": "grade_e3_eigo_b019", "subject": "eigo", "question": "「How old are you?」と聞かれて、「I'm eight.」と答えました。何才と言いましたか。数字で書きましょう。", "answer": "8", "hint": "eight は数のえい語だよ。", "explanation": "【何を聞かれているか】「How old are you?」と聞かれて、「I'm eight.」と答えました。\n\n【なぜそうなるのか】How old are you? は年れいをたずねる言い方で、I'm eight. は「ぼくは8才です」という意味だから。eight は数の8を表すえい語。\n\n【ステップ1】How old are you? は年れいをたずねる言い方。\n【ステップ2】答えの I'm eight. の eight は、数の8。\n【ステップ3】だから8才と言っている。\n\n【答え】8\n\n【たしかめ】one から数えて、eight が8番目になるか、ゆびをおりながらたしかめる。\n\n【よくあるまちがい】eighteen（18）とまちがえる。eight は8、eighteen は18。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b020", "subject": "eigo", "question": "「Are you Mai?」と聞かれました。あなたがマイさんです。「Yes, I ○○.」の○○に入るえい語を書きましょう。", "answer": "am", "hint": "「わたしは〜です」の意味の短いことばだよ。", "explanation": "【何を聞かれているか】「Are you Mai?」と聞かれました。\n\n【なぜそうなるのか】Are you ~? は「あなたは〜ですか」で、「はい、そうです」と答えるときは Yes, I am. と言うから。\n\n【ステップ1】「あなたはマイさんですか」と聞かれている。\n【ステップ2】自分がマイさんなので、「はい、そうです」と答える。\n【ステップ3】答えの言い方は Yes, I am. 。\n\n【答え】am\n\n【たしかめ】友だちに「Are you Mai?」と聞いてもらい、自分がマイさんのつもりで Yes, I am. と言ってみる。\n\n【よくあるまちがい】Yes, I'm. とのばして言ってしまう。Yes, I am. が正しい。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b021", "subject": "eigo", "question": "「Are you Ken?」と聞かれました。あなたはケンさんではありません。「No, I'm ○○.」の○○に入るえい語を書きましょう。", "answer": "not", "hint": "「〜ではない」を表す短いことばだよ。", "explanation": "【何を聞かれているか】「Are you Ken?」と聞かれました。\n\n【なぜそうなるのか】No, I'm not. は「いいえ、ちがいます」という意味で、not が「〜ではない」を表すから。\n\n【ステップ1】「いいえ、ちがう」と答える場面だと考える。\n【ステップ2】「〜ではない」を表すえい語は not。\n【ステップ3】I'm のあとに not を入れて、No, I'm not. になる。\n\n【答え】not\n\n【たしかめ】No, I'm not. を言ってみて、「いいえ、ちがいます」の意味になるかたしかめる。\n\n【よくあるまちがい】No, I am. と言ってしまう。それだと「いいえ、そうです」になっておかしい。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b022", "subject": "eigo", "question": "「How are you?」と聞かれて、元気なときの答えはどれですか。", "answer": "I'm fine.", "hint": "「元気です」という意味のことばをさがそう。", "explanation": "【何を聞かれているか】「How are you?」と聞かれて、元気なときの答えはどれですか。\n\n【なぜそうなるのか】How are you? は「元気ですか」と聞くあいさつで、元気なときは I'm fine. と答えるから。\n\n【ステップ1】How are you? は元気かどうかを聞いている。\n【ステップ2】I'm eight. は年れい、Goodbye. はわかれ。\n【ステップ3】「元気です」にあたるのは I'm fine. 。\n\n【答え】I'm fine.\n\n【たしかめ】2人で、「How are you?」「I'm fine.」と言い合って、話がつながるかたしかめる。\n\n【よくあるまちがい】I'm eight. と答えてしまう。それは年れいを答える言い方。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["I'm eight.", "I'm fine.", "Goodbye."]},
  {"id": "grade_e3_eigo_b023", "subject": "eigo", "question": "「I'm hungry.」は、どんな気持ちを言うえい語ですか。", "answer": "おなかがすいた", "hint": "食べものがほしくなったときのことだよ。", "explanation": "【何を聞かれているか】「I'm hungry.」は、どんな気持ちを言うえい語ですか。\n\n【なぜそうなるのか】hungry は「おなかがすいている」という意味で、I'm hungry. は「おなかがすいた」と言うときに使うから。\n\n【ステップ1】I'm のあとの hungry の意味を考える。\n【ステップ2】hungry は、食べたい気持ちをあらわす。\n【ステップ3】だから「おなかがすいた」。\n\n【答え】おなかがすいた\n\n【たしかめ】おなかをおさえて I'm hungry. と言ってみる。ジェスチャーと意味が合っているか見る。\n\n【よくあるまちがい】sleepy（ねむい）とまちがえる。hungry は食べもののこと。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["ねむい", "つかれた", "おなかがすいた"]},
  {"id": "grade_e3_eigo_b024", "subject": "eigo", "question": "ねむいときは、「I'm ○○.」と言います。○○に入るえい語を書きましょう。sではじまります。", "answer": "sleepy", "hint": "ねむくて、目がとじそうになるときの気持ちだよ。", "explanation": "【何を聞かれているか】ねむいときは、「I'm ○○.」と言います。\n\n【なぜそうなるのか】sleepy は「ねむい」という意味のえい語で、I'm sleepy. と言うと「ねむいです」になるから。つづりは s・l・e・e・p・y 。\n\n【ステップ1】「ねむい」気持ちをえい語で言う場面。\n【ステップ2】I'm のあとに気持ちを入れる。\n【ステップ3】ねむいは sleepy。\n\n【答え】sleepy\n\n【たしかめ】あくびをしながら I'm sleepy. と言ってみる。気持ちとことばが合えばよい。\n\n【よくあるまちがい】sleep（ねる）と書いて、さいごの y をわすれてしまう。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b025", "subject": "eigo", "question": "冬のさむい日に、外に出ました。「I'm ○○.」と言うとき、○○に入るえい語を書きましょう。", "answer": "cold", "hint": "体がぶるぶるふるえるときの気持ちだよ。", "explanation": "【何を聞かれているか】冬のさむい日に、外に出ました。\n\n【なぜそうなるのか】cold は「さむい」という意味で、さむく感じたとき I'm cold. と言うから。あつい日は I'm hot. と言う。\n\n【ステップ1】冬のさむい日の気持ちを考える。\n【ステップ2】さむいをあらわすえい語は cold。\n【ステップ3】I'm のあとに cold を入れて I'm cold. 。\n\n【答え】cold\n\n【たしかめ】体をぎゅっとちぢめて、I'm cold. と言ってみる。さむい様子が合っているか見る。\n\n【よくあるまちがい】hot と言ってしまう。hot はあつい。冬は cold 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b026", "subject": "eigo", "question": "数字の「5」を、えい語で書きましょう。fではじまります。", "answer": "five", "hint": "ゆびを1本ずつ立てて、5本まで数えよう。", "explanation": "【何を聞かれているか】数字の「5」を、えい語で書きましょう。\n\n【なぜそうなるのか】1から数えると、one, two, three, four, five とつづき、5番目のえい語が five だから。つづりは f・i・v・e の4文字。\n\n【ステップ1】1からじゅんに、えい語で数える。\n【ステップ2】one, two, three, four のつぎは five 。\n【ステップ3】f・i・v・e と書く。\n\n【答え】five\n\n【たしかめ】ゆびを1本ずつ立てながら数えて、5本目で five と言えるか見る。\n\n【よくあるまちがい】fife や fiv のように書いてしまう。さいごは e 。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b027", "subject": "eigo", "question": "「Three plus four is ○○.」の答えを、数字で書きましょう。", "answer": "7", "hint": "three は3、four は4だよ。", "explanation": "【何を聞かれているか】「Three plus four is ○○.」の答えを、数字で書きましょう。\n\n【なぜそうなるのか】Three plus four は「3たす4」で、3と4を合わせると7になるから。is は「は」にあたり、答えは seven と言う。\n\n【ステップ1】three は3、four は4、plus は「たす」。\n【ステップ2】3＋4を計算する。\n【ステップ3】3に4をたすと7。\n\n【答え】7\n\n【たしかめ】ゆびを3本出して、あと4本ふやすと7本になる。数えて7本になればよい。\n\n【よくあるまちがい】three と four のかけ算をしてしまう。plus は「たす」。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b028", "subject": "eigo", "question": "「nine」は、数字でいくつですか。", "answer": "9", "hint": "one からじゅんに数えて、9番目だよ。", "explanation": "【何を聞かれているか】「nine」は、数字でいくつですか。\n\n【なぜそうなるのか】nine は9をあらわすえい語で、eight（8）のつぎ、ten（10）の1つ前に来る数だから。\n\n【ステップ1】one からじゅんにえい語で数える。\n【ステップ2】seven, eight, nine, ten とつづく。\n【ステップ3】9番目が nine。\n\n【答え】9\n\n【たしかめ】ゆびをおりながら数えて、nine のところで9本目になるか見る。\n\n【よくあるまちがい】nineteen（19）とまちがえる。nine は9だけ。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["9", "6", "10"]},
  {"id": "grade_e3_eigo_b029", "subject": "eigo", "question": "「eleven」は、数字でいくつですか。数字で書きましょう。", "answer": "11", "hint": "ten のつぎの数だよ。", "explanation": "【何を聞かれているか】「eleven」は、数字でいくつですか。\n\n【なぜそうなるのか】eleven は ten（10）のつぎに来る数で、数字で書くと11になるから。11からは、1から10までとはちがう言い方になる。\n\n【ステップ1】ten（10）の数を思い出す。\n【ステップ2】10のつぎの数は11。\n【ステップ3】えい語で言うと eleven 。\n\n【答え】11\n\n【たしかめ】ten, eleven, twelve と声に出して、eleven が10のつぎに来るかたしかめる。\n\n【よくあるまちがい】1つ上の twelve（12）とまちがえる。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b030", "subject": "eigo", "question": "「thirteen」は、数字でいくつですか。", "answer": "13", "hint": "「thirteen」は、後ろの「teen」を強く言うよ。", "explanation": "【何を聞かれているか】「thirteen」は、数字でいくつですか。\n\n【なぜそうなるのか】thirteen のおわりの teen は「10をたした数」のしるしで、13を表すから。30は thirty と言い、前を強く言って言い分ける。\n\n【ステップ1】おわりが teen だと、13から19の数。\n【ステップ2】thirteen は、thir と teen がつながったことば。\n【ステップ3】13を表すのは thirteen 。\n\n【答え】13\n\n【たしかめ】thirteen と thirty を声に出して、後ろを強く言うほうが thirteen と聞き分ける。\n\n【よくあるまちがい】thirty（30）とまちがえる。teen で終わるのは13から19。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["3", "13", "30"]},
  {"id": "grade_e3_eigo_b031", "subject": "eigo", "question": "「nineteen」のつぎの数を、えい語で書きましょう。tではじまります。", "answer": "twenty", "hint": "19のつぎは、いくつかな。", "explanation": "【何を聞かれているか】「nineteen」のつぎの数を、えい語で書きましょう。\n\n【なぜそうなるのか】nineteen は19で、そのつぎの20は twenty と言うから。ここから先は、10ごとに言い方がかわる。\n\n【ステップ1】nineteen は19。\n【ステップ2】19のつぎは20。\n【ステップ3】えい語で20は twenty 。\n\n【答え】twenty\n\n【たしかめ】twenty を声に出して、19のつぎの数として言えるか見る。\n\n【よくあるまちがい】twelve（12）とまちがえる。twelve は12、twenty は20。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b032", "subject": "eigo", "question": "「zero」は、数字でいくつですか。数字で書きましょう。", "answer": "0", "hint": "なにもない、という意味の数だよ。", "explanation": "【何を聞かれているか】「zero」は、数字でいくつですか。\n\n【なぜそうなるのか】zero は「0」をあらわすえい語で、なにもないことを言うから。日本語の「ゼロ」より、すこしちがう音で言う。\n\n【ステップ1】zero はなにもない数だと考える。\n【ステップ2】なにもない数は0。\n【ステップ3】数字で書くと0。\n\n【答え】0\n\n【たしかめ】りんごを0こにして、「Zero apples.」と言ってみる。なにもないことが合っているか見る。\n\n【よくあるまちがい】one（1）と思ってしまう。zero は1つもないこと。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b033", "subject": "eigo", "question": "10ずつ数えます。「ten, twenty, thirty, ○○」の○○に入る、えい語を書きましょう。", "answer": "forty", "hint": "30のつぎの10のまとまりだよ。", "explanation": "【何を聞かれているか】10ずつ数えます。\n\n【なぜそうなるのか】ten（10）、twenty（20）、thirty（30）のつぎは40で、えい語では forty と書くから。つづりには u が入らない。\n\n【ステップ1】10ずつ数えていることをたしかめる。\n【ステップ2】30のつぎは40。\n【ステップ3】えい語で40は forty 。\n\n【答え】forty\n\n【たしかめ】forty を声に出して、10, 20, 30 と数えて40まで言えるか見る。\n\n【よくあるまちがい】fourty と、u を入れて書いてしまう。forty には u が入らない。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b034", "subject": "eigo", "question": "「How many?」は、何をたずねるえい語ですか。", "answer": "数", "hint": "物がいくつあるかを聞くよ。", "explanation": "【何を聞かれているか】「How many?」は、何をたずねるえい語ですか。\n\n【なぜそうなるのか】How many? は「いくつ？」と聞くことばで、物の数をたずねるときに使うから。答えるときは、Three apples. のように数と物を言う。\n\n【ステップ1】How many? の意味を考える。\n【ステップ2】「いくつ」と言いかえられる。\n【ステップ3】だから、聞いているのは「数」。\n\n【答え】数\n\n【たしかめ】りんごを3つ見せて、How many? と聞き、Three. と答えて話がつながるかたしかめる。\n\n【よくあるまちがい】What color?（何色？）とまちがえて、色を聞いていると思ってしまう。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["数", "色", "名前"]},
  {"id": "grade_e3_eigo_b035", "subject": "eigo", "question": "アルファベットは、全部で何文字ありますか。数字で書きましょう。", "answer": "26", "hint": "AからZまで、1文字ずつ数えるよ。", "explanation": "【何を聞かれているか】アルファベットは、全部で何文字ありますか。\n\n【なぜそうなるのか】アルファベットは A から Z まで、あわせて26文字だから。大文字も小文字も、文字の数は同じ26。\n\n【ステップ1】A から Z までをじゅんに数える。\n【ステップ2】A, B, C…と数えて、さいごの Z まで進める。\n【ステップ3】数えおわりは26。\n\n【答え】26\n\n【たしかめ】ABC のうたを1文字ずつゆびで数えて、さいごの Z で26になるか見る。\n\n【よくあるまちがい】大文字と小文字をあわせて52と答えてしまう。ひとつの文字として数えるので26。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b036", "subject": "eigo", "question": "小文字の「a」は、大文字ではどれですか。", "answer": "A", "hint": "形はちがうけれど、同じ名前の文字だよ。", "explanation": "【何を聞かれているか】小文字の「a」は、大文字ではどれですか。\n\n【なぜそうなるのか】アルファベットは、大文字と小文字で形がちがっても、同じ名前の文字がペアになっているから。a の大文字は A 。\n\n【ステップ1】a は小文字だと考える。\n【ステップ2】同じ名前の大文字をさがす。\n【ステップ3】a のペアは A 。\n\n【答え】A\n\n【たしかめ】a と A をならべて書き、2つとも「エー」と読めるか見る。\n\n【よくあるまちがい】a の大文字を Q とまちがえて書く。まるいところがにているが、べつの文字。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["Q", "O", "A"]},
  {"id": "grade_e3_eigo_b037", "subject": "eigo", "question": "「A, B, C, D, ○○」の○○に入る大文字を書きましょう。", "answer": "E", "hint": "ABC のうたのつづきだよ。", "explanation": "【何を聞かれているか】「A, B, C, D, ○○」の○○に入る大文字を書きましょう。\n\n【なぜそうなるのか】アルファベットは A, B, C, D, E のじゅんにならんでいて、D のつぎは E だから。うたに合わせて言うと、つづきを思い出しやすい。\n\n【ステップ1】ABC のうたを小さく歌う。\n【ステップ2】D のつぎの文字を思い出す。\n【ステップ3】D のつぎは E 。\n\n【答え】E\n\n【たしかめ】A から E まで、じゅんに声に出して言ってみる。E のところで終われば正しい。\n\n【よくあるまちがい】F とまちがえる。F は E のつぎの文字。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b038", "subject": "eigo", "question": "「apple」の1文字目は、大文字で書くとどれですか。", "answer": "A", "hint": "りんごのことばを、はじめの音で聞こう。", "explanation": "【何を聞かれているか】「apple」の1文字目は、大文字で書くとどれですか。\n\n【なぜそうなるのか】apple の1文字目は a で、大文字にすると A になるから。ことばの文字を1つずつ見ると、はじまりの文字がわかる。\n\n【ステップ1】apple のつづりを a・p・p・l・e と分ける。\n【ステップ2】1文字目は a 。\n【ステップ3】大文字にすると A 。\n\n【答え】A\n\n【たしかめ】apple を声に出して、はじめの音が「ア」に聞こえるかたしかめる。\n\n【よくあるまちがい】2文字目の p をえらんでしまう。1文字目を見る。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["B", "A", "E"]},
  {"id": "grade_e3_eigo_b039", "subject": "eigo", "question": "「T, U, ○○, W」の○○に入る大文字を書きましょう。", "answer": "V", "hint": "U のつぎの文字だよ。", "explanation": "【何を聞かれているか】「T, U, ○○, W」の○○に入る大文字を書きましょう。\n\n【なぜそうなるのか】アルファベットは T, U, V, W のじゅんにならんでいて、U と W のあいだに入るのは V だから。\n\n【ステップ1】T, U のつぎを思い出す。\n【ステップ2】W の前の文字をさがす。\n【ステップ3】U と W のあいだは V 。\n\n【答え】V\n\n【たしかめ】T から Z までをじゅんに言って、V のいちをたしかめる。\n\n【よくあるまちがい】X とまちがえる。X は W のつぎ。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b040", "subject": "eigo", "question": "小文字の「b」は、たて線の右と左のどちらにまるがありますか。「右」か「左」で答えましょう。", "answer": "右", "hint": "「b」の形を、ノートに書いてみよう。", "explanation": "【何を聞かれているか】小文字の「b」は、たて線の右と左のどちらにまるがありますか。\n\n【なぜそうなるのか】小文字の b は、たて線を左に書いて、まるを右につけるから。d はその反対で、まるが左にある。\n\n【ステップ1】b の形を思いうかべる。\n【ステップ2】たて線を先に書いて、右にまるをつける。\n【ステップ3】まるは右。\n\n【答え】右\n\n【たしかめ】ノートに b を書いて、まるが右に来ているか見る。d との形のちがいも見くらべる。\n\n【よくあるまちがい】d と同じと思って、まるを左にしてしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b041", "subject": "eigo", "question": "「E」と「F」で、よこ線が3本あるのは、どちらですか。", "answer": "E", "hint": "線の数を、ゆびで数えよう。", "explanation": "【何を聞かれているか】「E」と「F」で、よこ線が3本あるのは、どちらですか。\n\n【なぜそうなるのか】E は、上・中・下の3本のよこ線がある。F は上と中の2本だけで、下のよこ線がないから。\n\n【ステップ1】E の形を書く。\n【ステップ2】F の形を書く。\n【ステップ3】よこ線の数を数えると、E は3本、F は2本。\n\n【答え】E\n\n【たしかめ】紙に E と F を書いて、よこ線を数えてたしかめる。\n\n【よくあるまちがい】F にも下の線があると思ってしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["F", "I", "E"]},
  {"id": "grade_e3_eigo_b042", "subject": "eigo", "question": "小文字の「p」は、まるが、たて線の上と下のどちらにありますか。「上」か「下」で答えましょう。", "answer": "上", "hint": "p の形を書いて、まるの場所を見よう。", "explanation": "【何を聞かれているか】小文字の「p」は、まるが、たて線の上と下のどちらにありますか。\n\n【なぜそうなるのか】小文字の p は、たて線がまるより下まで出ていて、まるはたて線の上のほうについているから。q とは、まるの向きがちがう。\n\n【ステップ1】p の形を思いうかべる。\n【ステップ2】まるは右の上のほうにある。\n【ステップ3】たて線は下まで出ている。\n\n【答え】上\n\n【たしかめ】紙に p を書いて、まるが上に来るかたしかめる。\n\n【よくあるまちがい】まるが下にあると思ってしまう。下に出ているのはたて線。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b043", "subject": "eigo", "question": "「blue」は何色ですか。ひらがなで書きましょう。", "answer": "あお", "hint": "空やうみの色だよ。", "explanation": "【何を聞かれているか】「blue」は何色ですか。\n\n【なぜそうなるのか】blue は、空やうみの色をあらわす「あお」のえい語だから。色のことばは、まず見た色とことばをむすびつけておぼえる。\n\n【ステップ1】blue の意味を考える。\n【ステップ2】空やうみの色を思いうかべる。\n【ステップ3】それは「あお」。\n\n【答え】あお\n\n【たしかめ】青いものを見つけて、It's blue. と言えるかやってみる。\n\n【よくあるまちがい】green（みどり）とまちがえる。空の色が blue。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b044", "subject": "eigo", "question": "バナナの色は、えい語でどれですか。", "answer": "yellow", "hint": "バナナの皮を思いうかべよう。", "explanation": "【何を聞かれているか】バナナの色は、えい語でどれですか。\n\n【なぜそうなるのか】バナナの皮は黄色で、黄色のえい語は yellow だから。blue は青、green は緑で、色がちがう。\n\n【ステップ1】バナナの色を思いうかべる。\n【ステップ2】黄色のえい語は yellow 。\n【ステップ3】3つの中で、黄色なのは yellow だけ。\n\n【答え】yellow\n\n【たしかめ】yellow と言いながら、黄色いものを指さしてみる。\n\n【よくあるまちがい】green と答えてしまう。green は木の葉の色で、バナナのふつうの色は yellow 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["yellow", "blue", "green"]},
  {"id": "grade_e3_eigo_b045", "subject": "eigo", "question": "「green」は何色ですか。ひらがなで書きましょう。", "answer": "みどり", "hint": "木の葉の色だよ。", "explanation": "【何を聞かれているか】「green」は何色ですか。\n\n【なぜそうなるのか】green は、木の葉やくさの色をあらわす「みどり」のえい語だから。\n\n【ステップ1】green の意味を考える。\n【ステップ2】木の葉やくさの色を思いうかべる。\n【ステップ3】それは「みどり」。\n\n【答え】みどり\n\n【たしかめ】みどり色のものを見つけて、It's green. と言ってみる。\n\n【よくあるまちがい】blue（あお）とまちがえる。くさの色は green 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b046", "subject": "eigo", "question": "「purple」は何色ですか。ひらがなで書きましょう。", "answer": "むらさき", "hint": "ぶどうの色に近いよ。", "explanation": "【何を聞かれているか】「purple」は何色ですか。\n\n【なぜそうなるのか】purple は、赤と青がまざったようなむらさき色をあらわすえい語だから。ぶどうの色などを思いうかべるとおぼえやすい。\n\n【ステップ1】purple の意味を考える。\n【ステップ2】赤と青をまぜた色を思いうかべる。\n【ステップ3】それは「むらさき」。\n\n【答え】むらさき\n\n【たしかめ】むらさき色のものを見つけて、It's purple. と言ってみる。\n\n【よくあるまちがい】pink（もも色）とまちがえる。pink は、うすい赤のようなもも色。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b047", "subject": "eigo", "question": "「brown」は何色ですか。ひらがなで書きましょう。", "answer": "ちゃいろ", "hint": "土や、チョコレートの色だよ。", "explanation": "【何を聞かれているか】「brown」は何色ですか。\n\n【なぜそうなるのか】brown は、土やチョコレートのような「ちゃいろ」のえい語だから。木のえだや、くまの毛の色にも使う。\n\n【ステップ1】brown の意味を考える。\n【ステップ2】土やチョコレートの色を思いうかべる。\n【ステップ3】それは「ちゃいろ」。\n\n【答え】ちゃいろ\n\n【たしかめ】ちゃいろの物を見つけて、It's brown. と言ってみる。\n\n【よくあるまちがい】black（くろ）とまちがえる。brown は少しうすい色。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b048", "subject": "eigo", "question": "「circle」は、どんな形ですか。", "answer": "まる", "hint": "ボールをまっすぐ前から見た形だよ。", "explanation": "【何を聞かれているか】「circle」は、どんな形ですか。\n\n【なぜそうなるのか】circle はまるい形をあらわすえい語で、角がなくて、ぐるっとつながった形だから。\n\n【ステップ1】circle の意味を考える。\n【ステップ2】形のえい語を思い出す。\n【ステップ3】まるい形が circle 。\n\n【答え】まる\n\n【たしかめ】まるいもので近いものをさがして、It's a circle. と言ってみる。\n\n【よくあるまちがい】triangle（三角）や square（四角）とまちがえる。circle には角がない。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["三角", "まる", "四角"]},
  {"id": "grade_e3_eigo_b049", "subject": "eigo", "question": "「triangle」の角は、いくつありますか。数字で書きましょう。", "answer": "3", "hint": "三角の形を、紙に書いてみよう。", "explanation": "【何を聞かれているか】「triangle」の角は、いくつありますか。\n\n【なぜそうなるのか】triangle は三角形のことで、角が3つあるから。\n\n【ステップ1】triangle は三角の形。\n【ステップ2】紙に三角形を書く。\n【ステップ3】角の数を数えると3つ。\n\n【答え】3\n\n【たしかめ】三角形を書いて、角を1つずつ指でさしながら3つ数える。\n\n【よくあるまちがい】square（四角）の角の4つと、まちがえる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b050", "subject": "eigo", "question": "「star」は、日本語で何ですか。", "answer": "ほし", "hint": "夜の空にたくさん光っているよ。", "explanation": "【何を聞かれているか】「star」は、日本語で何ですか。\n\n【なぜそうなるのか】star は、夜空に光る星のことで、形をあらわすときにも使うから。五つの角のある、とがった形をあらわす。\n\n【ステップ1】star の意味を考える。\n【ステップ2】夜の空や形のえい語を思い出す。\n【ステップ3】star は「ほし」。\n\n【答え】ほし\n\n【たしかめ】夜空の星と、星の形をえがいた絵を見て、star と言ってみる。\n\n【よくあるまちがい】moon（つき）とまちがえる。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["ほし", "つき", "たいよう"]},
  {"id": "grade_e3_eigo_b051", "subject": "eigo", "question": "「pencil」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "えんぴつ", "hint": "字を書くときに使うよ。", "explanation": "【何を聞かれているか】「pencil」は、日本語で何ですか。\n\n【なぜそうなるのか】pencil は、字や絵をかくときに使う「えんぴつ」のえい語だから。pen は「ペン」で、べつのもの。\n\n【ステップ1】pencil の意味を考える。\n【ステップ2】学校でノートに字を書く道具を思いうかべる。\n【ステップ3】それは「えんぴつ」。\n\n【答え】えんぴつ\n\n【たしかめ】えんぴつを手に持って、This is a pencil. と言ってみる。\n\n【よくあるまちがい】pen（ペン）と同じだと思ってしまう。pencil は えんぴつ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b052", "subject": "eigo", "question": "「eraser」は、日本語で何ですか。", "answer": "けしゴム", "hint": "まちがえた字を、きれいにするよ。", "explanation": "【何を聞かれているか】「eraser」は、日本語で何ですか。\n\n【なぜそうなるのか】eraser は、書いた字や絵をけすための「けしゴム」のえい語だから。\n\n【ステップ1】eraser の意味を考える。\n【ステップ2】字をまちがえたときに使う物を思い出す。\n【ステップ3】それは「けしゴム」。\n\n【答え】けしゴム\n\n【たしかめ】けしゴムを持って、It's an eraser. と言ってみる。\n\n【よくあるまちがい】pencil（えんぴつ）とまちがえる。字を書くのが pencil 、けすのが eraser 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["えんぴつ", "ノート", "けしゴム"]},
  {"id": "grade_e3_eigo_b053", "subject": "eigo", "question": "「notebook」は、日本語で何ですか。カタカナで書きましょう。", "answer": "ノート", "hint": "じゅぎょうで字を書きうつすものだよ。", "explanation": "【何を聞かれているか】「notebook」は、日本語で何ですか。\n\n【なぜそうなるのか】notebook は、字や絵をかく「ノート」のえい語だから。book は「本」、note は「書きつけ」の意味で、2つがつながったことば。\n\n【ステップ1】notebook は、2つのことばがつながっている。\n【ステップ2】字を書くための book のようなものと考える。\n【ステップ3】それは「ノート」。\n\n【答え】ノート\n\n【たしかめ】ノートを持って、It's a notebook. と言ってみる。\n\n【よくあるまちがい】book（本）と同じだと思ってしまう。notebook は字を書くためのノート。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b054", "subject": "eigo", "question": "「scissors」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "はさみ", "hint": "紙を切るときに使うよ。", "explanation": "【何を聞かれているか】「scissors」は、日本語で何ですか。\n\n【なぜそうなるのか】scissors は、紙などを切るための「はさみ」のえい語だから。はが2まいあるので、つづりの終わりに s がつく。\n\n【ステップ1】scissors の意味を考える。\n【ステップ2】紙を切る道具を思いうかべる。\n【ステップ3】それは「はさみ」。\n\n【答え】はさみ\n\n【たしかめ】はさみを持って、Scissors. と言ってみる。\n\n【よくあるまちがい】glue（のり）とまちがえる。切るのが scissors、はるのが glue。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b055", "subject": "eigo", "question": "「clock」は、日本語で何ですか。漢字2字で書きましょう。", "answer": "時計", "hint": "教室のかべにかかっているよ。", "explanation": "【何を聞かれているか】「clock」は、日本語で何ですか。\n\n【なぜそうなるのか】clock は、時間を見るための「時計」のえい語だから。教室のかべにかかっている clock で、じゅぎょうの時間を知る。\n\n【ステップ1】clock の意味を考える。\n【ステップ2】教室で時間を見るものを思いうかべる。\n【ステップ3】それは「時計」。\n\n【答え】時計\n\n【たしかめ】教室の時計を指さして、It's a clock. と言ってみる。\n\n【よくあるまちがい】door（ドア）や window（まど）とまちがえる。時間を知るのが clock。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b056", "subject": "eigo", "question": "えんぴつを見せて、「What's this?」と聞かれました。「It's a ○○.」の○○に入るえい語を書きましょう。", "answer": "pencil", "hint": "見せているものは、字を書くものだよ。", "explanation": "【何を聞かれているか】えんぴつを見せて、「What's this?」と聞かれました。\n\n【なぜそうなるのか】What's this? は「これは何ですか」と物の名前をたずねる言い方で、見せているものの名前を入れて答えるから。えんぴつなら pencil 。\n\n【ステップ1】What's this? は物の名前をたずねている。\n【ステップ2】見せているのは えんぴつ。\n【ステップ3】It's a pencil. と答える。\n\n【答え】pencil\n\n【たしかめ】2人で、物を見せながら What's this? と聞いて、It's a pencil. と答え合ってみる。\n\n【よくあるまちがい】pen と答えてしまう。見せているものを、よく見る。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b057", "subject": "eigo", "question": "りんごを見せて、「It's ○○ apple.」と言います。○○に入るのは、どれですか。", "answer": "an", "hint": "apple の1文字目の音を聞こう。", "explanation": "【何を聞かれているか】りんごを見せて、「It's ○○ apple.」と言います。\n\n【なぜそうなるのか】a は「ひとつの」という目じるしで、あいうえおのような音ではじまることばの前では an を使うから。apple は「ア」ではじまるので an apple 。\n\n【ステップ1】It's ○○ apple. の ○○ は「ひとつの」を表す。\n【ステップ2】apple は「ア」の音ではじまる。\n【ステップ3】「ア」のような音の前では an を使う。\n\n【答え】an\n\n【たしかめ】an apple と声に出して、すっとつながるか聞く。a apple と言うと言いにくい。\n\n【よくあるまちがい】a だけを使って、a apple と言ってしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["a", "an", "two"]},
  {"id": "grade_e3_eigo_b058", "subject": "eigo", "question": "先生が「Sit down.」と言いました。どうしますか。ひらがなで書きましょう。", "answer": "すわる", "hint": "立っていたら、どうするかな。", "explanation": "【何を聞かれているか】先生が「Sit down.」と言いました。\n\n【なぜそうなるのか】Sit down. は「すわってください」という意味で、先生の言いつけだから。sit が「すわる」、down が「下へ」の意味。\n\n【ステップ1】先生が言ったことを考える。\n【ステップ2】sit は「すわる」。\n【ステップ3】だから、いすに「すわる」。\n\n【答え】すわる\n\n【たしかめ】Sit down. と言われたつもりで、体を動かしてみる。いすにすわる動きになれば正しい。\n\n【よくあるまちがい】Stand up.（立つ）とまちがえる。Sit down. はすわる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b059", "subject": "eigo", "question": "先生が「Listen.」と言いました。何をしますか。漢字1字で書きましょう。", "answer": "聞", "hint": "耳を使うよ。", "explanation": "【何を聞かれているか】先生が「Listen.」と言いました。\n\n【なぜそうなるのか】Listen. は「聞いてください」という意味で、先生の話や音をよく聞くようにという言いつけだから。\n\n【ステップ1】Listen. の意味を考える。\n【ステップ2】Look. は「見る」、Listen. は耳で何をするか。\n【ステップ3】それは「聞く」。\n\n【答え】聞\n\n【たしかめ】Listen. と言われたとき、耳に手をあててみる。耳を使うことなら正しい。\n\n【よくあるまちがい】Look.（見る）とまちがえる。Listen. は耳を使う。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b060", "subject": "eigo", "question": "「head」は、体のどこですか。漢字1字で書きましょう。", "answer": "頭", "hint": "ぼうし（ぼうし）をかぶるところだよ。", "explanation": "【何を聞かれているか】「head」は、体のどこですか。\n\n【なぜそうなるのか】head は、体のいちばん上にある「頭」のえい語だから。頭の下に、顔や首がある。\n\n【ステップ1】head の意味を考える。\n【ステップ2】体のいちばん上を思いうかべる。\n【ステップ3】それは「頭」。\n\n【答え】頭\n\n【たしかめ】自分の頭に手をのせて、head と言ってみる。\n\n【よくあるまちがい】shoulders（かた）とまちがえる。head は体のいちばん上。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b061", "subject": "eigo", "question": "「nose」は、顔のどこですか。ひらがなで書きましょう。", "answer": "はな", "hint": "においをかぐところだよ。", "explanation": "【何を聞かれているか】「nose」は、顔のどこですか。\n\n【なぜそうなるのか】nose は、顔のまん中にあって、においをかぐ「はな」のえい語だから。\n\n【ステップ1】nose の意味を考える。\n【ステップ2】においをかぐところを思いうかべる。\n【ステップ3】それは「はな」。\n\n【答え】はな\n\n【たしかめ】自分のはなを指さして、nose と言ってみる。\n\n【よくあるまちがい】mouth（くち）とまちがえる。nose はにおいをかぐところ。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b062", "subject": "eigo", "question": "「ears」は、顔のどこですか。漢字1字で書きましょう。", "answer": "耳", "hint": "音を聞くところだよ。", "explanation": "【何を聞かれているか】「ears」は、顔のどこですか。\n\n【なぜそうなるのか】ears は、音を聞くための「耳」のえい語で、2つあるから、ことばの終わりに s がつく。\n\n【ステップ1】ears の意味を考える。\n【ステップ2】音を聞くところを思いうかべる。\n【ステップ3】それは「耳」。\n\n【答え】耳\n\n【たしかめ】両方の耳に手をあてて、ears と言ってみる。\n\n【よくあるまちがい】eyes（目）とまちがえる。ears は音を聞くところ。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b063", "subject": "eigo", "question": "「foot」は、体のどこですか。漢字1字で書きましょう。", "answer": "足", "hint": "くつをはくところだよ。", "explanation": "【何を聞かれているか】「foot」は、体のどこですか。\n\n【なぜそうなるのか】foot は、くつをはく足の先の部分をあらわすえい語で、日本語では「足」にあたるから。\n\n【ステップ1】foot の意味を考える。\n【ステップ2】くつをはくところを思いうかべる。\n【ステップ3】それは「足」。\n\n【答え】足\n\n【たしかめ】自分の足を指さして、foot と言ってみる。\n\n【よくあるまちがい】hand（手）とまちがえる。foot は足の方。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b064", "subject": "eigo", "question": "「Simon says, stand up.」のときだけ立つゲームをしています。「Stand up.」とだけ言われました。立ちますか。「はい」か「いいえ」で答えましょう。", "answer": "いいえ", "hint": "「Simon says」が言われていないよ。", "explanation": "【何を聞かれているか】「Simon says, stand up.」のときだけ立つゲームをしています。\n\n【なぜそうなるのか】このゲームでは、「Simon says」と言ったときだけ動いて、それが言われなかったときは動かないというきまりだから。\n\n【ステップ1】ゲームのきまりを思い出す。\n【ステップ2】言われたのは Stand up. だけ。\n【ステップ3】Simon says がないので、動かない。\n\n【答え】いいえ\n\n【たしかめ】2人で、「Simon says, stand up.」のときだけ立つ練習をしてみる。\n\n【よくあるまちがい】言われたとおりに立ってしまう。Simon says が先に言われたときだけ動く。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b065", "subject": "eigo", "question": "「mother」は、日本語で何ですか。", "answer": "お母さん", "hint": "自分を生んだ人の、女の人だよ。", "explanation": "【何を聞かれているか】「mother」は、日本語で何ですか。\n\n【なぜそうなるのか】mother は、自分を生んだ女の親をよぶことばで、日本語では「お母さん」にあたるから。男の親は father で、お父さん。\n\n【ステップ1】mother の意味を考える。\n【ステップ2】father は「お父さん」と対になるえい語。\n【ステップ3】女の親だから「お母さん」。\n\n【答え】お母さん\n\n【たしかめ】家の人の顔を思いうかべて、This is my mother. と言ってみる。\n\n【よくあるまちがい】father（お父さん）とまちがえる。mother は女の親。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["お父さん", "お姉さん", "お母さん"]},
  {"id": "grade_e3_eigo_b066", "subject": "eigo", "question": "「grandfather」は、日本語で何ですか。", "answer": "おじいさん", "hint": "お父さんやお母さんの、お父さんのことだよ。", "explanation": "【何を聞かれているか】「grandfather」は、日本語で何ですか。\n\n【なぜそうなるのか】grandfather は、お父さんやお母さんのお父さんで、日本語では「おじいさん」にあたるから。grandmother は、おばあさん。\n\n【ステップ1】grandfather の意味を考える。\n【ステップ2】father（お父さん）に grand がついている。\n【ステップ3】お父さんのお父さんは「おじいさん」。\n\n【答え】おじいさん\n\n【たしかめ】This is my grandfather. と言ってみる。おじいさんの顔を思いうかべればよい。\n\n【よくあるまちがい】grandmother（おばあさん）とまちがえる。father が入っていれば男の人。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["おじいさん", "おばあさん", "お父さん"]},
  {"id": "grade_e3_eigo_b067", "subject": "eigo", "question": "「sister」は、男の子と女の子のどちらですか。「男の子」か「女の子」で答えましょう。", "answer": "女の子", "hint": "brother（兄・弟）とちがう方だよ。", "explanation": "【何を聞かれているか】「sister」は、男の子と女の子のどちらですか。\n\n【なぜそうなるのか】sister は、お姉さんや妹のことで、きょうだいのうち女の子をあらわすから。男の子のきょうだいは brother 。\n\n【ステップ1】sister の意味を考える。\n【ステップ2】brother は男の子のきょうだい。\n【ステップ3】sister は女の子のきょうだい。\n\n【答え】女の子\n\n【たしかめ】This is my sister. と言いながら、女の子の絵を指さしてみる。\n\n【よくあるまちがい】brother と同じだと思ってしまう。brother は男の子。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b068", "subject": "eigo", "question": "「apple」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "りんご", "hint": "赤くて、まるいくだものだよ。", "explanation": "【何を聞かれているか】「apple」は、日本語で何ですか。\n\n【なぜそうなるのか】apple は、赤や緑でまるい「りんご」のえい語だから。りんごの形をした絵と、ことばをむすびつけておぼえる。\n\n【ステップ1】apple の意味を考える。\n【ステップ2】赤くてまるいくだものを思いうかべる。\n【ステップ3】それは「りんご」。\n\n【答え】りんご\n\n【たしかめ】りんごの絵を見て、Apple. と言ってみる。\n\n【よくあるまちがい】peach（もも）とまちがえる。りんごは apple 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b069", "subject": "eigo", "question": "「grapes」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "ぶどう", "hint": "小さな実がたくさんついているよ。", "explanation": "【何を聞かれているか】「grapes」は、日本語で何ですか。\n\n【なぜそうなるのか】grapes は、小さな実がふさになってついた「ぶどう」のえい語だから。実がいくつもあるので、ことばの終わりに s がつく。\n\n【ステップ1】grapes の意味を考える。\n【ステップ2】小さな実が、ふさになったくだものを思いうかべる。\n【ステップ3】それは「ぶどう」。\n\n【答え】ぶどう\n\n【たしかめ】ぶどうを思いうかべて、Grapes. と言ってみる。\n\n【よくあるまちがい】apples（りんご）とまちがえる。apples と grapes のつづりを見くらべる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b070", "subject": "eigo", "question": "「carrot」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "にんじん", "hint": "オレンジ色で、細長いやさいだよ。", "explanation": "【何を聞かれているか】「carrot」は、日本語で何ですか。\n\n【なぜそうなるのか】carrot は、オレンジ色で細長いやさいの「にんじん」のえい語だから。うさぎがよく食べるものとしても知られている。\n\n【ステップ1】carrot の意味を考える。\n【ステップ2】オレンジ色の細長いやさいを思いうかべる。\n【ステップ3】それは「にんじん」。\n\n【答え】にんじん\n\n【たしかめ】にんじんの絵を見て、Carrot. と言ってみる。\n\n【よくあるまちがい】onion（たまねぎ）とまちがえる。carrot はオレンジ色。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b071", "subject": "eigo", "question": "「potato」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "じゃがいも", "hint": "カレーに入っている、土の中でそだつやさいだよ。", "explanation": "【何を聞かれているか】「potato」は、日本語で何ですか。\n\n【なぜそうなるのか】potato は、土の中でそだつ「じゃがいも」のえい語だから。カレーやフライドポテトに使われる。\n\n【ステップ1】potato の意味を考える。\n【ステップ2】土の中でそだつやさいを思いうかべる。\n【ステップ3】それは「じゃがいも」。\n\n【答え】じゃがいも\n\n【たしかめ】フライドポテトを思いうかべて、Potato. と言ってみる。\n\n【よくあるまちがい】tomato（トマト）とまちがえる。1文字目が p か t かで見分ける。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b072", "subject": "eigo", "question": "「egg」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "たまご", "hint": "にわとりが生むものだよ。", "explanation": "【何を聞かれているか】「egg」は、日本語で何ですか。\n\n【なぜそうなるのか】egg は、にわとりなどが生む「たまご」のえい語だから。たまごやきやゆでたまごなど、りょうりにもよく使う。\n\n【ステップ1】egg の意味を考える。\n【ステップ2】にわとりが生むものを思いうかべる。\n【ステップ3】それは「たまご」。\n\n【答え】たまご\n\n【たしかめ】たまごを手に持つつもりで、Egg. と言ってみる。\n\n【よくあるまちがい】つづりの g を1つにして、eg と書いてしまう。egg は g が2つ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b073", "subject": "eigo", "question": "「water」は、日本語で何ですか。", "answer": "みず", "hint": "のどがかわいたときにのむよ。", "explanation": "【何を聞かれているか】「water」は、日本語で何ですか。\n\n【なぜそうなるのか】water は、のむことも、手をあらうこともできる「みず」のえい語だから。tea（お茶）や juice（ジュース）とはちがう。\n\n【ステップ1】water の意味を考える。\n【ステップ2】のどがかわいたときにのむ、色のないものを思いうかべる。\n【ステップ3】それは「みず」。\n\n【答え】みず\n\n【たしかめ】コップに入れた水を見て、Water. と言ってみる。\n\n【よくあるまちがい】tea（お茶）とまちがえる。water は色のない水。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["おちゃ", "みず", "ぎゅうにゅう"]},
  {"id": "grade_e3_eigo_b074", "subject": "eigo", "question": "「I like apples.」は、どんな意味ですか。", "answer": "りんごがすきです。", "hint": "like は、気に入っているという意味だよ。", "explanation": "【何を聞かれているか】「I like apples.」は、どんな意味ですか。\n\n【なぜそうなるのか】like は「すき」という意味で、I like apples. は「わたしはりんごがすきです」と気持ちをつたえる言い方だから。\n\n【ステップ1】I like のあとに、すきな物を入れる。\n【ステップ2】apples は、りんごのこと。\n【ステップ3】全体で「りんごがすきです」。\n\n【答え】りんごがすきです。\n\n【たしかめ】2人で、I like apples. と言い合って、すきな物が同じか聞いてみる。\n\n【よくあるまちがい】I want apples.（りんごがほしい）とまちがえる。like はすきという気持ち。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["りんごがすきです。", "りんごがきらいです。", "りんごをたべました。"]},
  {"id": "grade_e3_eigo_b075", "subject": "eigo", "question": "「Do you like cats?」と聞かれて、ねこがすきなので「はい」と答えます。「Yes, I ○○.」の○○に入るえい語を書きましょう。", "answer": "do", "hint": "「する」という意味のことばで、聞かれたことばをくりかえすよ。", "explanation": "【何を聞かれているか】「Do you like cats?」と聞かれて、ねこがすきなので「はい」と答えます。\n\n【なぜそうなるのか】Do you like ~? には、Yes, I do. と答えるきまりで、聞かれた Do をくりかえすから。\n\n【ステップ1】Do you like cats? は、ねこがすきかを聞いている。\n【ステップ2】「はい」の答えは Yes, I do. 。\n【ステップ3】do を入れる。\n\n【答え】do\n\n【たしかめ】2人で、Do you like cats? と聞いて、Yes, I do. と答えてみる。\n\n【よくあるまちがい】Yes, I like. と答えてしまう。Yes, I do. が正しい答え方。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b076", "subject": "eigo", "question": "お店で「Here you are.」と言って、何かをわたされました。そのあと言うのはどれですか。", "answer": "Thank you.", "hint": "物をもらったら、お礼を言うよ。", "explanation": "【何を聞かれているか】お店で「Here you are.」と言って、何かをわたされました。\n\n【なぜそうなるのか】Here you are. は「はい、どうぞ」という意味で、わたされたら「ありがとう」と答えるから。わたす人が You're welcome. と返すと、会話がつながる。\n\n【ステップ1】「はい、どうぞ」と物をわたされた場面。\n【ステップ2】もらったら、お礼を言う。\n【ステップ3】お礼のことばは Thank you. 。\n\n【答え】Thank you.\n\n【たしかめ】2人で、お店ごっこをして、Here you are. と Thank you. を言い合ってみる。\n\n【よくあるまちがい】Goodbye. と言ってしまう。お礼を言ってからわかれる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["Good night.", "Excuse me.", "Thank you."]},
  {"id": "grade_e3_eigo_b077", "subject": "eigo", "question": "「dog」は、日本語で何ですか。漢字1字で書きましょう。", "answer": "犬", "hint": "「ワンワン」となく動物だよ。", "explanation": "【何を聞かれているか】「dog」は、日本語で何ですか。\n\n【なぜそうなるのか】dog は、よく人にかわれていて、「ワンワン」となく「犬」のえい語だから。えい語では woof woof と聞こえる。\n\n【ステップ1】dog の意味を考える。\n【ステップ2】よく人にかわれている動物を思いうかべる。\n【ステップ3】それは「犬」。\n\n【答え】犬\n\n【たしかめ】犬の絵を見て、Dog. と言ってみる。\n\n【よくあるまちがい】cat（ねこ）とまちがえる。犬は dog 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b078", "subject": "eigo", "question": "「cat」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "ねこ", "hint": "「ニャー」となく動物だよ。", "explanation": "【何を聞かれているか】「cat」は、日本語で何ですか。\n\n【なぜそうなるのか】cat は、小さくて、「ニャー」となく「ねこ」のえい語だから。えい語では meow と聞こえる。\n\n【ステップ1】cat の意味を考える。\n【ステップ2】ニャーとなく動物を思いうかべる。\n【ステップ3】それは「ねこ」。\n\n【答え】ねこ\n\n【たしかめ】ねこの絵を見て、Cat. と言ってみる。\n\n【よくあるまちがい】dog（犬）とまちがえる。ねこは cat 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b079", "subject": "eigo", "question": "「fish」は、日本語で何ですか。漢字1字で書きましょう。", "answer": "魚", "hint": "水の中をおよぐよ。", "explanation": "【何を聞かれているか】「fish」は、日本語で何ですか。\n\n【なぜそうなるのか】fish は、水の中をおよぐ「魚」のえい語だから。川やうみ、水そうにいる。\n\n【ステップ1】fish の意味を考える。\n【ステップ2】水の中をおよぐ生き物を思いうかべる。\n【ステップ3】それは「魚」。\n\n【答え】魚\n\n【たしかめ】水そうの絵を見て、Fish. と言ってみる。\n\n【よくあるまちがい】bird（鳥）とまちがえる。fish は水の中。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b080", "subject": "eigo", "question": "「rabbit」は、日本語で何ですか。", "answer": "うさぎ", "hint": "耳が長くて、ぴょんぴょんはねるよ。", "explanation": "【何を聞かれているか】「rabbit」は、日本語で何ですか。\n\n【なぜそうなるのか】rabbit は、耳が長くてはねる動物の「うさぎ」のえい語だから。mouse は「ねずみ」、turtle は「かめ」で、ちがう動物。\n\n【ステップ1】rabbit の意味を考える。\n【ステップ2】耳が長くてはねる動物を思いうかべる。\n【ステップ3】それは「うさぎ」。\n\n【答え】うさぎ\n\n【たしかめ】うさぎが耳を立てるまねをして、Rabbit. と言ってみる。\n\n【よくあるまちがい】mouse（ねずみ）とまちがえる。耳が長いのは rabbit 。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["ねずみ", "うさぎ", "かめ"]},
  {"id": "grade_e3_eigo_b081", "subject": "eigo", "question": "「elephant」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "ぞう", "hint": "長い鼻をもつ、大きな動物だよ。", "explanation": "【何を聞かれているか】「elephant」は、日本語で何ですか。\n\n【なぜそうなるのか】elephant は、長い鼻と大きな体をもつ「ぞう」のえい語だから。動物園でも人気がある。\n\n【ステップ1】elephant の意味を考える。\n【ステップ2】長い鼻の大きな動物を思いうかべる。\n【ステップ3】それは「ぞう」。\n\n【答え】ぞう\n\n【たしかめ】ぞうが鼻をゆらすまねをして、Elephant. と言ってみる。\n\n【よくあるまちがい】giraffe（きりん）とまちがえる。きりんは首が長い。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b082", "subject": "eigo", "question": "「monkey」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "さる", "hint": "木にのぼるのが上手だよ。", "explanation": "【何を聞かれているか】「monkey」は、日本語で何ですか。\n\n【なぜそうなるのか】monkey は、木をのぼるのが上手な「さる」のえい語だから。\n\n【ステップ1】monkey の意味を考える。\n【ステップ2】木をのぼる動物を思いうかべる。\n【ステップ3】それは「さる」。\n\n【答え】さる\n\n【たしかめ】さるのまねをして、Monkey. と言ってみる。\n\n【よくあるまちがい】bear（くま）とまちがえる。monkey はさる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b083", "subject": "eigo", "question": "牛（うし）のなき声は、えい語では「○○」と聞こえます。どれですか。", "answer": "moo", "hint": "ゆっくり、のびるような声だよ。", "explanation": "【何を聞かれているか】牛（うし）のなき声は、えい語では「○○」と聞こえます。\n\n【なぜそうなるのか】えい語では、牛の声を moo と書くきまりだから。日本語の「モー」に近い聞こえ方になる。pig は oink oink 、duck は quack quack 。\n\n【ステップ1】牛のなき声を思い出す。\n【ステップ2】cow は moo 、pig は oink、duck は quack 。\n【ステップ3】牛は moo 。\n\n【答え】moo\n\n【たしかめ】moo と言って、牛のまねをしてみる。日本語の「モー」に近い。\n\n【よくあるまちがい】oink と答えてしまう。oink は pig の声。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["oink", "quack", "moo"]},
  {"id": "grade_e3_eigo_b084", "subject": "eigo", "question": "えい語で、duck（アヒル）はどんな声でなくと言いますか。「○○ ○○」の○○に入る、えい語1つを書きましょう。", "answer": "quack", "hint": "アヒルのなき声のことだよ。", "explanation": "【何を聞かれているか】えい語で、duck（アヒル）はどんな声でなくと言いますか。\n\n【なぜそうなるのか】えい語では、アヒルのなき声を quack quack と書くから。日本語の「ガーガー」とは、聞こえ方がちがう。\n\n【ステップ1】duck のなき声を考える。\n【ステップ2】えい語での決まった言い方を思い出す。\n【ステップ3】duck は quack quack 。\n\n【答え】quack\n\n【たしかめ】quack quack と言いながら、アヒルのまねをしてみる。\n\n【よくあるまちがい】moo と答えてしまう。moo は cow の声。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b085", "subject": "eigo", "question": "「It's sunny.」の天気は、どれですか。", "answer": "はれ", "hint": "空に太陽が出ているよ。", "explanation": "【何を聞かれているか】「It's sunny.」の天気は、どれですか。\n\n【なぜそうなるのか】sunny は、sun（太陽）がかがやいている天気をあらわし、日本語では「はれ」にあたるから。\n\n【ステップ1】sunny の意味を考える。\n【ステップ2】sun は「太陽」。\n【ステップ3】太陽が出ている天気は「はれ」。\n\n【答え】はれ\n\n【たしかめ】空に太陽がある絵を見て、It's sunny. と言ってみる。\n\n【よくあるまちがい】rainy（あめ）とまちがえる。sunny は太陽が出ている天気。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["はれ", "あめ", "ゆき"]},
  {"id": "grade_e3_eigo_b086", "subject": "eigo", "question": "「It's rainy.」の天気は、どれですか。漢字1字で書きましょう。", "answer": "雨", "hint": "空から水がふってくるよ。", "explanation": "【何を聞かれているか】「It's rainy.」の天気は、どれですか。\n\n【なぜそうなるのか】rainy は、空から雨がふっている天気をあらわし、日本語では「雨」にあたるから。rain は「雨」のえい語。\n\n【ステップ1】rainy の意味を考える。\n【ステップ2】rain は「雨」。\n【ステップ3】雨がふっている天気は「雨」。\n\n【答え】雨\n\n【たしかめ】雨の絵を見て、It's rainy. と言ってみる。\n\n【よくあるまちがい】snowy（雪）とまちがえる。rainy は雨。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b087", "subject": "eigo", "question": "「It's cloudy.」の天気は、どれですか。ひらがなで書きましょう。", "answer": "くもり", "hint": "空に雲がいっぱい広がっているよ。", "explanation": "【何を聞かれているか】「It's cloudy.」の天気は、どれですか。\n\n【なぜそうなるのか】cloudy は、雲におおわれた天気をあらわし、日本語では「くもり」にあたるから。cloud は「雲」のえい語。\n\n【ステップ1】cloudy の意味を考える。\n【ステップ2】cloud は「雲」。\n【ステップ3】雲が広がる天気は「くもり」。\n\n【答え】くもり\n\n【たしかめ】雲の多い空の絵を見て、It's cloudy. と言ってみる。\n\n【よくあるまちがい】sunny（はれ）とまちがえる。cloudy は雲が多い天気。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b088", "subject": "eigo", "question": "「It's windy.」の天気は、どれですか。漢字1字で書きましょう。", "answer": "風", "hint": "木のえだや、はたがゆれているよ。", "explanation": "【何を聞かれているか】「It's windy.」の天気は、どれですか。\n\n【なぜそうなるのか】windy は、風がふいている天気をあらわし、日本語では「風」にあたるから。wind は「風」のえい語。\n\n【ステップ1】windy の意味を考える。\n【ステップ2】wind は「風」。\n【ステップ3】風がふいている天気は「風」。\n\n【答え】風\n\n【たしかめ】風にゆれる木の絵を見て、It's windy. と言ってみる。\n\n【よくあるまちがい】rainy（雨）とまちがえる。windy は風。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b089", "subject": "eigo", "question": "雪がふっています。「How's the weather?」と聞かれたら、「It's ○○.」と答えます。○○に入るえい語を書きましょう。", "answer": "snowy", "hint": "「雪」のえい語は snow だよ。", "explanation": "【何を聞かれているか】雪がふっています。\n\n【なぜそうなるのか】How's the weather? は「天気はどうですか」と聞く言い方で、雪がふっていれば It's snowy. と答えるから。snow は「雪」で、y をつけると天気をあらわす。\n\n【ステップ1】How's the weather? は天気を聞いている。\n【ステップ2】雪がふっているので、雪の天気をあらわす。\n【ステップ3】それは snowy 。\n\n【答え】snowy\n\n【たしかめ】雪の絵を見て、How's the weather? と聞き、It's snowy. と答えてみる。\n\n【よくあるまちがい】sunny と答えてしまう。sunny は太陽が出ている天気。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b090", "subject": "eigo", "question": "「spring」は、日本語で何ですか。漢字1字で書きましょう。", "answer": "春", "hint": "さくらがさくきせつだよ。", "explanation": "【何を聞かれているか】「spring」は、日本語で何ですか。\n\n【なぜそうなるのか】spring は、あたたかくなって花がさくきせつの「春」のえい語だから。summer は夏、fall は秋、winter は冬。\n\n【ステップ1】spring の意味を考える。\n【ステップ2】さくらがさくきせつを思いうかべる。\n【ステップ3】それは「春」。\n\n【答え】春\n\n【たしかめ】さくらの絵を見て、It's spring. と言ってみる。\n\n【よくあるまちがい】summer（夏）とまちがえる。spring は春。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b091", "subject": "eigo", "question": "「fall」は、日本語で何ですか。", "answer": "あき", "hint": "木の葉が赤や黄色にかわるきせつだよ。", "explanation": "【何を聞かれているか】「fall」は、日本語で何ですか。\n\n【なぜそうなるのか】fall は、きせつの「秋」を言うえい語だから。autumn とも言う。アメリカでは fall がよく使われる。\n\n【ステップ1】fall の意味を考える。\n【ステップ2】spring, summer, fall, winter のじゅんにならべる。\n【ステップ3】3番目は「あき」。\n\n【答え】あき\n\n【たしかめ】spring, summer, fall, winter と指をおって、fall が3番目になるか見る。\n\n【よくあるまちがい】fall を「落ちる」だけだと思ってしまう。きせつをあらわすときは「あき」。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["はる", "あき", "なつ"]},
  {"id": "grade_e3_eigo_b092", "subject": "eigo", "question": "「What day is it?」と聞かれて、「It's Sunday.」と答えました。何曜日と言いましたか。「○曜日」の○に入る漢字を書きましょう。", "answer": "日", "hint": "1週間のさいごや、はじめの休みの日だよ。", "explanation": "【何を聞かれているか】「What day is it?」と聞かれて、「It's Sunday.」と答えました。\n\n【なぜそうなるのか】Sunday は日曜日にあたるえい語だから。What day is it? は「今日は何曜日ですか」と聞く言い方。\n\n【ステップ1】What day is it? は曜日を聞いている。\n【ステップ2】Sunday は日曜日。\n【ステップ3】○に入る漢字は「日」。\n\n【答え】日\n\n【たしかめ】2人で、What day is it? と聞いて、It's Sunday. と答えてみる。\n\n【よくあるまちがい】Monday（月曜日）とまちがえる。Sunday は日曜日。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b093", "subject": "eigo", "question": "「baseball」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "やきゅう", "hint": "ボールをバットでうつスポーツだよ。", "explanation": "【何を聞かれているか】「baseball」は、日本語で何ですか。\n\n【なぜそうなるのか】baseball は、ボールをバットでうって、ベースをまわるスポーツの「やきゅう」のえい語だから。base は「ベース」で、ball は「ボール」。\n\n【ステップ1】baseball の意味を考える。\n【ステップ2】ball は「ボール」、base は「ベース」。\n【ステップ3】ボールをバットでうつスポーツは「やきゅう」。\n\n【答え】やきゅう\n\n【たしかめ】バットをふるまねをして、Baseball. と言ってみる。\n\n【よくあるまちがい】soccer（サッカー）とまちがえる。baseball はバットを使う。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b094", "subject": "eigo", "question": "「swimming」は、日本語で何ですか。ひらがなで書きましょう。", "answer": "すいえい", "hint": "プールや海で体を動かすよ。", "explanation": "【何を聞かれているか】「swimming」は、日本語で何ですか。\n\n【なぜそうなるのか】swimming は、水の中でおよぐ「すいえい」のえい語で、およぐという意味の swim がもとになっているから。\n\n【ステップ1】swimming の意味を考える。\n【ステップ2】swim は「およぐ」。\n【ステップ3】およぐスポーツは「すいえい」。\n\n【答え】すいえい\n\n【たしかめ】およぐまねをして、Swimming. と言ってみる。\n\n【よくあるまちがい】tennis（テニス）とまちがえる。swimming は水の中。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b095", "subject": "eigo", "question": "ボールを高いところにあるバスケットに入れるスポーツは、えい語でどれですか。", "answer": "basketball", "hint": "「バスケット」と「ボール」がつながったことばだよ。", "explanation": "【何を聞かれているか】ボールを高いところにあるバスケットに入れるスポーツは、えい語でどれですか。\n\n【なぜそうなるのか】basketball は、basket（かご）と ball（ボール）がつながったことばで、ボールをかごに入れるスポーツだから。\n\n【ステップ1】ボールをかごに入れるスポーツを考える。\n【ステップ2】basket と ball をつなぐ。\n【ステップ3】basketball になる。\n\n【答え】basketball\n\n【たしかめ】basket と ball を声に出して、つなげて言えるか見る。\n\n【よくあるまちがい】soccer をえらんでしまう。サッカーは足でボールをける。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["basketball", "soccer", "tennis"]},
  {"id": "grade_e3_eigo_b096", "subject": "eigo", "question": "「What sport do you like?」は、何をたずねるえい語ですか。", "answer": "すきなスポーツ", "hint": "sport は「スポーツ」、like は「すき」だよ。", "explanation": "【何を聞かれているか】「What sport do you like?」は、何をたずねるえい語ですか。\n\n【なぜそうなるのか】What sport do you like? は「どんなスポーツがすきですか」という意味で、sport が「スポーツ」、like が「すき」だから。\n\n【ステップ1】言葉を分けて意味を考える。\n【ステップ2】sport は「スポーツ」、like は「すき」。\n【ステップ3】聞いているのは「すきなスポーツ」。\n\n【答え】すきなスポーツ\n\n【たしかめ】2人で、What sport do you like? と聞いて、I like soccer. と答えてみる。\n\n【よくあるまちがい】すきな色を聞いていると思ってしまう。sport はスポーツ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["すきな色", "すきなたべもの", "すきなスポーツ"]},
  {"id": "grade_e3_eigo_b097", "subject": "eigo", "question": "「Japan」は、日本語で何ですか。漢字2字で書きましょう。", "answer": "日本", "hint": "わたしたちがすんでいる国だよ。", "explanation": "【何を聞かれているか】「Japan」は、日本語で何ですか。\n\n【なぜそうなるのか】Japan は、わたしたちがすんでいる国の名前で、日本語では「日本」というから。\n\n【ステップ1】Japan の意味を考える。\n【ステップ2】わたしたちのすんでいる国を考える。\n【ステップ3】それは「日本」。\n\n【答え】日本\n\n【たしかめ】I'm from Japan. と言ってみて、自分の国の名前が言えているか見る。\n\n【よくあるまちがい】China（中国）とまちがえる。Japan は日本。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b098", "subject": "eigo", "question": "「China」は、日本語で何ですか。漢字2字で書きましょう。", "answer": "中国", "hint": "日本のとなりにある大きな国だよ。", "explanation": "【何を聞かれているか】「China」は、日本語で何ですか。\n\n【なぜそうなるのか】China は、日本の西にある国の名前で、日本語では「中国」というから。\n\n【ステップ1】China の意味を考える。\n【ステップ2】日本のとなりの大きな国を思いうかべる。\n【ステップ3】それは「中国」。\n\n【答え】中国\n\n【たしかめ】地図で日本のとなりの国をさがして、China と言ってみる。\n\n【よくあるまちがい】Japan（日本）とまちがえる。China は中国。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b099", "subject": "eigo", "question": "「karate」は、日本語で何ですか。漢字2字で書きましょう。", "answer": "空手", "hint": "日本で生まれた、手と足を使うスポーツだよ。", "explanation": "【何を聞かれているか】「karate」は、日本語で何ですか。\n\n【なぜそうなるのか】karate は、日本で生まれた、手と足を使う「空手」のことで、えい語でも karate とよばれて世界中で使われるから。\n\n【ステップ1】karate は日本のことばだと考える。\n【ステップ2】手と足を使う、日本のスポーツを思いうかべる。\n【ステップ3】それは「空手」。\n\n【答え】空手\n\n【たしかめ】空手のかまえのまねをして、Karate. と言ってみる。\n\n【よくあるまちがい】judo（じゅうどう）とまちがえる。karate は手や足でうつ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_eigo_b100", "subject": "eigo", "question": "「origami」は、日本のことばです。ひらがな5文字で書きましょう。", "answer": "おりがみ", "hint": "紙をおって、つるなどを作るよ。", "explanation": "【何を聞かれているか】「origami」は、日本のことばです。\n\n【なぜそうなるのか】origami は、紙をおって形をつくる日本のあそびの「おりがみ」で、えい語でも origami と言って世界に広まっているから。\n\n【ステップ1】origami は日本のことばだと考える。\n【ステップ2】紙をおってつるを作るあそびを思いうかべる。\n【ステップ3】それは「おりがみ」。\n\n【答え】おりがみ\n\n【たしかめ】紙をおるまねをして、Origami. と言ってみる。\n\n【よくあるまちがい】「おりかみ」と書いてしまう。「かみ」が、くっつくと「がみ」とにごる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
];
